function N(x){return Math.round(x).toLocaleString('ja-JP');}
var pd=Math.max(1,+v('perday')||1), age=Math.max(0,+v('age')||0), price=Math.max(0,+v('price')||0);
var total=pd*365*age, cost=total*price;
Crowd.pile(el,{title:'おむつを積み上げると', unit:'枚', bars:[{label:'1年分',value:pd*365},{label:'卒業まで',value:total}],
  fmtv:function(x){return N(x)+'枚';},
  final:function(){return '卒業まで約 '+N(total)+'枚、費用は ¥'+N(cost)+'。毎日の育児、お疲れさまです。';}});
